-- NaCCA curriculum for Basic 7 (part 2 of 2): 165 indicators (Mathematics, Religious & Moral Education, Science, Social Studies).
-- Needs 20261029_curriculum_subject_key.sql first. Safe to run again: it replaces these subjects for Basic 7.
delete from public.curriculum_items
 where lower(class_name) = 'basic 7' and subject_key in ('maths', 'rme', 'science', 'social studies');

